head.script:
function nkUseMyLocation(btn) {

    var form = btn.form;
    var status = form.querySelector('.nk-gps-status');

    if (!navigator.geolocation) {
        alert('GPS is not supported in this browser.');
        return;
    }

    status.textContent = 'Getting your location...';

    navigator.geolocation.getCurrentPosition(
        function (pos) {

            form.querySelector('input[name=latitude]').value = pos.coords.latitude;
            form.querySelector('input[name=longitude]').value = pos.coords.longitude;

            status.textContent = 'Location captured. Finding place name...';

            var fd = new FormData();
            fd.append('csrf_token', form.querySelector('input[name=csrf_token]').value);
            fd.append('latitude', pos.coords.latitude);
            fd.append('longitude', pos.coords.longitude);

            fetch('/nk_salesperson/expense/place', {
                method: 'POST',
                body: fd,
                credentials: 'same-origin'
            })
            .then(function (r) { return r.json(); })
            .then(function (res) {
                if (res.place) {
                    form.querySelector('input[name=location]').value = res.place;
                }
                form.querySelector('input[name=address]').value = res.address || '';
                status.textContent = res.place
                    ? ('Location: ' + res.place)
                    : 'GPS captured. Please type the location name.';
            })
            .catch(function () {
                status.textContent = 'GPS captured. Please type the location name.';
            });
        },
        function () {
            status.textContent = 'Could not get your location. Allow location permission or type it.';
        },
        {enableHighAccuracy: true, timeout: 20000, maximumAge: 0}
    );
}


function nkToggleEdit(id) {

    var r =
        document.getElementById(
            'nk-edit-' + id
        );

    if (!r) {
        return;
    }

    r.style.display =
        (
            r.style.display === 'none'
        )
        ? 'table-row'
        : 'none';
}


/* =================================================
   CALCULATE TOTAL
================================================= */

function nkCalculateExpenseTotal(form) {

    var fields = [
        'travel_amount',
        'food_amount',
        'hotel_amount',
        'fuel_amount',
        'mobile_amount',
        'other_amount'
    ];

    var total = 0;

    fields.forEach(
        function(fieldName) {

            var field =
                form.querySelector(
                    'input[name="' +
                    fieldName +
                    '"]'
                );

            if (field) {

                var value =
                    parseFloat(
                        field.value || 0
                    );

                if (!isNaN(value)) {

                    total += value;

                }

            }

        }
    );

    var totalElement =
        form.querySelector(
            '.nk-live-expense-total'
        );

    if (totalElement) {

        totalElement.textContent =
            total.toFixed(2);

    }

}


/* =================================================
   VALIDATE EXPENSE AMOUNT
================================================= */

function nkValidateExpense(form) {

    var fields = [
        'travel_amount',
        'food_amount',
        'hotel_amount',
        'fuel_amount',
        'mobile_amount',
        'other_amount'
    ];

    var total = 0;

    fields.forEach(
        function(fieldName) {

            var field =
                form.querySelector(
                    'input[name="' +
                    fieldName +
                    '"]'
                );

            if (field) {

                var value =
                    parseFloat(
                        field.value || 0
                    );

                if (!isNaN(value)) {
                    total += value;
                }

            }

        }
    );

    if (total <= 0) {

        alert(
            'Please enter at least one expense amount.'
        );

        return false;
    }

    return true;
}

main.script:
(function () {

    var box = document.getElementById('nk-track');
    var csrf = box.dataset.csrf;
    var interval = parseInt(box.dataset.interval, 10) * 1000;
    var timer = null;
    var wakeLock = null;

    function show(id, visible) {
        document.getElementById(id).style.display = visible ? 'inline-block' : 'none';
    }

    function setStatus(text, info) {
        document.getElementById('nk-track-status').textContent = text;
        document.getElementById('nk-track-info').textContent = info || '';
    }

    function post(url, data) {
        var fd = new FormData();
        fd.append('csrf_token', csrf);
        Object.keys(data || {}).forEach(function (k) {
            fd.append(k, data[k]);
        });
        return fetch(url, {method: 'POST', body: fd, credentials: 'same-origin'})
            .then(function (r) { return r.json(); });
    }

    function getPosition(onOk) {
        if (!navigator.geolocation) {
            alert('This browser does not support GPS location.');
            return;
        }
        navigator.geolocation.getCurrentPosition(onOk, function (err) {
            if (err.code === 1) {
                alert('Location permission was denied. Please allow location to start tracking.');
                stopLocal();
            } else {
                setStatus('Tracking is ON.', 'Waiting for GPS signal...');
            }
        }, {enableHighAccuracy: true, timeout: 25000, maximumAge: 0});
    }

    function coords(pos) {
        return {
            latitude: pos.coords.latitude,
            longitude: pos.coords.longitude,
            accuracy: pos.coords.accuracy
        };
    }

    function lockScreen() {
        try {
            if (navigator.wakeLock) {
                navigator.wakeLock.request('screen').then(function (l) { wakeLock = l; });
            }
        } catch (e) {}
    }

    function ping() {
        getPosition(function (pos) {
            post('/nk_salesperson/tracking/ping', coords(pos)).then(function (res) {
                if (res.stopped) {
                    stopLocal();
                    return;
                }
                if (res.ok) {
                    var when = res.time ? new Date(res.time) : new Date();
                    setStatus('Tracking is ON.',
                        'Last update: ' + when.toLocaleTimeString() +
                        ' (accuracy ' + Math.round(res.accuracy || 0) + ' m)');
                }
            });
        });
    }

    function schedule() {
        if (timer) { clearInterval(timer); }
        timer = setInterval(ping, interval);
        lockScreen();
        show('nk-track-start', false);
        show('nk-track-stop', true);
    }

    function stopLocal() {
        if (timer) { clearInterval(timer); timer = null; }
        try { if (wakeLock) { wakeLock.release(); wakeLock = null; } } catch (e) {}
        show('nk-track-start', true);
        show('nk-track-stop', false);
        setStatus('Tracking is OFF.', '');
    }

    window.nkStartTracking = function () {
        getPosition(function (pos) {
            post('/nk_salesperson/tracking/start', coords(pos)).then(function (res) {
                if (res.ok) {
                    setStatus('Tracking is ON.', 'Location captured.');
                    schedule();
                } else {
                    alert('Could not start tracking. Please login again.');
                }
            });
        });
    };

    window.nkStopTracking = function () {
        post('/nk_salesperson/tracking/stop', {}).then(function () {
            stopLocal();
        });
    };

    if (box.dataset.active === '1') {
        schedule();
        ping();
    }

})();

head.script:
function nkProdChange(sel) {

    var opt =
        sel.options[
            sel.selectedIndex
        ];

    var p =
        opt.getAttribute(
            'data-price'
        );

    var row =
        sel.parentNode.parentNode;

    row.querySelector(
        'input[name=price]'
    ).value =
        p ? p : '';

}


function nkAddLine() {

    var tb =
        document.getElementById(
            'nk-lines'
        );

    var r =
        tb.rows[
            tb.rows.length - 1
        ].cloneNode(true);

    r.querySelector(
        'select'
    ).selectedIndex = 0;

    r.querySelector(
        'input[name=price]'
    ).value = '';

    tb.appendChild(r);

}
